def inr_format(n):
    if n < 0:
        raise ValueError("Only non-negative integers are allowed")
    num_str = str(n)[::-1]
    formatted = []
    for i, digit in enumerate(num_str):
        if i % 2 == 0 and i < len(num_str) - 3:
            formatted.append(digit)
        elif i % 2 == 1:
            formatted.append(',')
            formatted.append(digit)
        else:
            formatted.append(digit)
    return ''.join(formatted[::-1])

def inr_format(amount):
    if amount == 0:
        return '0'
    elif amount < 1000:
        return str(amount)
    else:
        return f"{amount // 100:02d},{(amount // 10) % 100:02d},{amount % 100:03d}"

